FIELDS = ["action_key", "risk_level", "severity", "asset_criticality",
          "environment", "integration", "playbook", "initiator_kind"]

for policy in sorted(policies, key=lambda p: p.get("priority", 500)):
    if not policy.get("enabled", True):
        continue
    criteria = policy.get("match", {})
    if all(criteria.get(field) in (None, request.get(field)) for field in FIELDS):
        decision = dict(policy)
        if request.get("risk_level") == "high":
            if decision.get("effect") == "allow":
                decision["effect"] = "require_approval"
                decision["required_approvals"] = 1
                decision["separation_of_duty"] = True
                decision["override_reason"] = (
                    "a high-risk action cannot be auto-approved by policy"
                )
            if decision.get("on_timeout") == "proceed":
                decision["on_timeout"] = "reject"
        return decision

return {"name": "implicit deny", "effect": "deny",
        "reason": "no policy matched; the platform does not guess"}
